def cmp_semver(a, b):
    def parse(v):
        # Ignore build metadata
        base_version = v.split('+')[0]
        parts = base_version.split('.')

        # Major, Minor, Patch
        main = [int(x) for x in parts[:3]]

        # Pre-release identifiers
        pre_release = []
        if len(parts) > 3:
            for p in parts[3:]:
                if p.isdigit():
                    pre_release.append(int(p))
                else:
                    pre_release.append(p)
        return main, pre_release

    a_main, a_pre = parse(a)
    b_main, b_pre = parse(b)

    # Compare Major, Minor, Patch
    if a_main < b_main:
        return -1
    if a_main > b_main:
        return 1

    # Pre-release vs Release logic
    # A version WITH a pre-release sorts BEFORE the same version without one
    if a_pre and not b_pre:
        return -1
    if not a_pre and b_pre:
        return 1
    if not a_pre and not b_pre:
        return 0

    # Compare pre-release identifiers left to right
    for ap, bp in zip(a_pre, b_pre):
        is_a_num = isinstance(ap, int)
        is_b_num = isinstance(bp, int)

        if is_a_num and is_b_num:
            if ap < bp: return -1
            if ap > bp: return 1
        elif not is_a_num and not is_b_num:
            if ap < bp: return -1
            if ap > bp: return 1
        else:
            # Numeric identifiers sort before alphanumeric ones
            return -1 if is_a_num else 1

    # Longer identifier list wins if all preceding are equal
    if len(a_pre) < len(b_pre):
        return -1
    if len(a_pre) > len(b_pre):
        return 1

    return 0
