def parse_range(header, size):
    if not header.startswith("bytes="):
        return None

    content = header[6:]
    if not content:
        return None

    ranges = content.split(",")
    results = []

    for r in ranges:
        r = r.strip()
        if not r:
            continue

        try:
            if "-" in r:
                parts = r.split("-")
                if len(parts) != 2:
                    return None
                p1, p2 = parts[0].strip(), parts[1].strip()

                if not p1 and p2: # Case: -500
                    val = int(p2)
                    start = max(0, size - val)
                    end = size - 1
                    if start < size:
                        results.append((start, end))
                elif p1 and not p2: # Case: 500-
                    start = int(p1)
                    end = size - 1
                    if start < size:
                        results.append((start, end))
                elif p1 and p2: # Case: 0-499
                    start = int(p1)
                    end = int(p2)
                    if start < size:
                        results.append((start, min(end, size - 1)))
                else: # Case: -
                    return None
            else: # Case: 0
                start = int(r)
                end = size - 1
                if start < size:
                    results.append((start, end))
        except ValueError:
            return None

    return results if results else None
```

