def unified_diff(a, b, context=3):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    diff = []
    i, j = m, n
    while i > 0 or j > 0:
        if i > 0 and j > 0 and a[i-1] == b[j-1]:
            diff.append((' ', a[i-1]))
            i -= 1
            j -= 1
        elif j > 0 and (i == 0 or dp[i][j-1] >= dp[i-1][j]):
            diff.append(('+', b[j-1]))
            j -= 1
        else:
            diff.append(('-', a[i-1]))
            i -= 1
    diff.reverse()

    changes = [k for k, op in enumerate(diff) if op[0] in ('-', '+')]
    if not changes:
        return []

    hunks = []
    current_hunk = [changes[0]]
    for k in range(1, len(changes)):
        prev_idx = changes[k-1]
        curr_idx = changes[k]
        num_context_between = 0
        for idx in range(prev_idx + 1, curr_idx):
            if diff[idx][0] == ' ':
                num_context_between += 1

        if num_context_between <= 2 * context:
            current_hunk.append(curr_idx)
        else:
            hunks.append(current_hunk)
            current_hunk = [curr_idx]
    hunks.append(current_hunk)

    output = []
    for hunk in hunks:
        h_start_idx = hunk[0]
        count = 0
        for idx in range(h_start_idx - 1, -1, -1):
            if diff[idx][0] == ' ':
                count += 1
            else:
                break
            if count == context:
                h_start_idx = idx
                break

        h_end_idx = hunk[-1]
        count = 0
        for idx in range(h_end_idx + 1, len(diff)):
            if diff[idx][0] == ' ':
                count += 1
            else:
                break
            if count == context:
                h_end_idx = idx
                break

        diff_slice = diff[h_start_idx : h_end_idx + 1]

        a_idx = 0
        b_idx = 0
        for idx in range(h_start_idx):
            op, _ = diff[idx]
            if op == ' ':
                a_idx += 1
                b_idx += 1
            elif op == '-':
                a_idx += 1
            elif op == '+':
                b_idx += 1

        a_start = a_idx + 1
        b_start = b_idx + 1

        a_len = 0
        b_len = 0
        for op, _ in diff_slice:
            if op == ' ':
                a_len += 1
                b_len += 1
            elif op == '-':
                a_len += 1
            elif op == '+':
                b_len += 1

        output.append(f"@@ -{a_start},{a_len} +{b_start},{b_len} @@")
        for op, line in diff_slice:
            if op == ' ':
                output.append(f" {line}")
            else:
                output.append(f"{op}{line}")

    return output
