import datetime

def next_fire(expr, after):
    def parse_field(f_str, min_v, max_v):
        if f_str == '*':
            return set(range(min_v, max_v + 1)), False

        res = set()
        parts = f_str.split(',')
        for part in parts:
            if '/' in part:
                base, step_s = part.split('/')
                step = int(step_s)
                if step <= 0: raise ValueError

                if base == '*':
                    start, end = min_v, max_v
                elif '-' in base:
                    start, end = map(int, base.split('-'))
                else:
                    start = int(base)
                    end = max_v

                if start < min_v or end > max_v or start > end:
                    raise ValueError

                for v in range(start, end + 1, step):
                    res.add(v)
            else:
                if '-' in part:
                    start, end = map(int, part.split('-'))
                    if start < min_v or end > max_v or start > end:
                        raise ValueError
                    res.update(range(start, end + 1))
                else:
                    val = int(part)
                    if val < min_v or val > max_v:
                        raise ValueError
                    res.add(val)
        return res, True

    try:
        fields = expr.split()
        if len(fields) != 5:
            raise ValueError

        parsed = []
        # (min, max) for (minute, hour, day-of-month, month, day-of-week)
        ranges = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 6)]

        for i, (f_str, (min_v, max_v)) in enumerate(zip(fields, ranges)):
            parsed.append(parse_field(f_str, min_v, max_v))

        def is_match(t):
            # parsed indices: 0:min, 1:hour, 2:dom, 3:month, 4:dow
            if parsed[3][1] and t.month not in parsed[3][0]: return False
            if parsed[1][1] and t.hour not in parsed[1][0]: return False
            if parsed[0][1] and t.minute not in parsed[0][0]: return False

            dom_set, dom_res = parsed[2]
            dow_set, dow_res = parsed[4]

            if dom_res and dow_res:
                t_dom = t.day
                t_dow = (t.weekday() + 1) % 7
                if t_dom not in dom_set and t_dow not in dow_set:
                    return False
            elif dom_res:
                if t.day not in dom_set:
                    return False
            elif dow_res:
                t_dow = (t.weekday() + 1) % 7
                if t_dow not in dow_set:
                    return False
            return True

        curr = after + datetime.timedelta(seconds=1)
        if curr.microsecond > 0:
            curr = curr.replace(microsecond=0)
        if curr.second > 0:
            curr = (curr + datetime.timedelta(seconds=60 - curr.second)).replace(microsecond=0)

        while True:
            if is_match(curr):
                return curr
            curr += datetime.timedelta(minutes=1)

    except Exception:
        raise ValueError("Malformed expression")
