class WildcardTrie:
    def __init__(self):
        # Each node is a dictionary: 
        # 'children': {char: node_dict}
        # 'count': number of words ending at this node
        self.root = {'children': {}, 'count': 0}

    def add(self, word: str) -> None:
        node = self.root
        for char in word:
            if char not in node['children']:
                node['children'][char] = {'children': {}, 'count': 0}
            node = node['children'][char]
        node['count'] += 1

    def remove(self, word: str) -> bool:
        node = self.root
        for char in word:
            if char not in node['children']:
                return False
            node = node['children'][char]

        if node['count'] > 0:
            node['count'] -= 1
            return True
        return False

    def search(self, pattern: str) -> list[str]:
        results = []

        def dfs(node, index, path):
            if index == len(pattern):
                # If we reached the end of the pattern, check if a word ends here
                for _ in range(node['count']):
                    results.append("".join(path))
                return

            char = pattern[index]
            if char == '.':
                # Wildcard: explore all possible child branches
                for child_char, next_node in node['children'].items():
                    path.append(child_char)
                    dfs(next_node, index + 1, path)
                    path.pop()
            else:
                # Literal: move to the specific child branch
                if char in node['children']:
                    path.append(char)
                    dfs(node['children'][char], index + 1, path)
                    path.pop()

        dfs(self.root, 0, [])
        return sorted(results)

```

