def to_base(n, alphabet):
    if n == 0:
        return alphabet[0]

    base = len(alphabet)
    is_negative = n < 0
    n = abs(n)

    digits = []
    while n > 0:
        digits.append(alphabet[n % base])
        n //= base

    if is_negative:
        digits.append('-')

    return "".join(reversed(digits))

def from_base(s, alphabet):
    if not s:
        raise ValueError("Empty string")

    base = len(alphabet)
    char_to_int = {char: i for i, char in enumerate(alphabet)}

    is_negative = False
    start_idx = 0

    if s[0] == '-':
        if len(s) == 1:
            raise ValueError("Invalid string")
        is_negative = True
        start_idx = 1

    res = 0
    for i in range(start_idx, len(s)):
        char = s[i]
        if char not in char_to_int:
            raise ValueError("Character not in alphabet")
        res = res * base + char_to_int[char]

    return -res if is_negative else res
```

