def deep_copy(obj, memo=None):
    if memo is None:
        memo = {}

    # Return scalars as-is
    if obj is None or isinstance(obj, (str, int, float, bool)):
        return obj

    obj_id = id(obj)
    if obj_id in memo:
        return memo[obj_id]

