import heapq
from collections import defaultdict

def shortest_path(graph, src, dst):
    # 1. Build the reverse graph to find the shortest path from any node to dst.
    # In the reverse graph, an edge (u, v) with weight w becomes (v, u) with weight w.
    rev_graph = defaultdict(list)
    for u in graph:
        for v, w in graph[u]:
            rev_graph[v].append((u, w))

    # 2. Dijkstra's algorithm from dst on the reverse graph.
    # dist[u] will store the pair (min_cost, min_edges) from node u to dst.
    # We use a tuple (cost, edges) so that the priority queue naturally 
    # prioritizes minimum cost first, then minimum number of edges.
    dist = {dst: (0, 0)}
    pq = [(0, 0, dst)]

    while pq:
        d, e, u = heapq.heappop(pq)

        if (d, e) > dist.get(u, (float('inf'), float('inf'))):
            continue

        for v, w in rev_graph.get(u, []):
            new_dist = (d + w, e + 1)
            if new_dist < dist.get(v, (float('inf'), float('inf'))):
                dist[v] = new_dist
                heapq.heappush(pq, (new_dist[0], new_dist[1], v))

    # If src is not reachable from dst in the reverse graph, it's unreachable in the original.
    if src not in dist:
        return (None, [])

    # 3. Greedy path construction from src to dst.
    # At each step, we pick the neighbor that is part of a shortest path (min cost, min edges)
    # and has the smallest node label to satisfy the lexicographical requirement.
    path = [src]
    curr = src
    while curr != dst:
        candidates = []
        # Check all neighbors of the current node in the original graph.
        for v, w in graph.get(curr, []):
            if v in dist:
                d_v, e_v = dist[v]
                # A neighbor v is on a shortest path if the cost/edges to dst 
                # via v matches the optimal cost/edges from the current node.
                if (d_v + w, e_v + 1) == dist[curr]:
                    candidates.append(v)

        if not candidates:
            # This part should technically not be reached if src is in dist.
            break

        # Pick the lexicographically smallest node among valid candidates.
        next_node = min(candidates)
        path.append(next_node)
        curr = next_node

    return (dist[src][0], path)

