function deepEqual(a, b, visited = new WeakMap()) {
  // SameValueZero: NaN equals NaN, +0 equals -0
  if (a === b || (Number.isNaN(a) && Number.isNaN(b))) {
    return true;
  }

  // Values of different types are never equal
  if (typeof a !== typeof b || a === null || b === null || typeof a !== 'object') {
    return false;
  }

  // Ensure they are the same internal class (e.g., Array vs Object)
  if (Object.prototype.toString.call(a) !== Object.prototype.toString.call(b)) {
    return false;
  }

  // Cycle detection: track pairs of objects being compared
  if (visited.has(a)) {
    return visited.get(a) === b;
  }
  visited.set(a, b);

  // Date comparison
  if (a instanceof Date && b instanceof Date) {
    return a.getTime() === b.getTime();
  }

  // RegExp comparison
  if (a instanceof RegExp && b instanceof RegExp) {
    return a.source === b.source && a.flags === b.flags;
  }

  // Map comparison (irrespective of insertion order)
  if (a instanceof Map && b instanceof Map) {
    if (a.size !== b.size) return false;
    for (let [aKey, aVal] of a) {
      let found = false;
      for (let [bKey, bVal] of b) {
        if (deepEqual(aKey, bKey, visited) && deepEqual(aVal, bVal, visited)) {
          found = true;
          break;
        }
      }
      if (!found) return false;
    }
    return true;
  }

  // Set comparison (irrespective of insertion order)
  if (a instanceof Set && b instanceof Set) {
    if (a.size !== b.size) return false;
    for (let aVal of a) {
      let found = false;
      for (let bVal of b) {
        if (deepEqual(aVal, bVal, visited)) {
          found = true;
          break;
        }
      }
      if (!found) return false;
    }
    return true;
  }

  // Array comparison
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i], visited)) return false;
    }
    return true;
  }

  // Plain Object comparison (own enumerable keys)
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);

  if (keysA.length !== keysB.length) return false;

  for (const key of keysA) {
    if (!Object.prototype.hasOwnProperty.call(b, key) || !deepEqual(a[key], b[key], visited)) {
      return false;
    }
  }

  return true;
}

module.exports = deepEqual;
