function pLimit(n) {
  let activeCount = 0;
  const queue = [];

  return function(fn) {
    return new Promise((resolve, reject) => {
      queue.push({ fn, resolve, reject });

      const runNext = () => {
        if (queue.length === 0) return;

        activeCount++;
        const { fn: task, resolve: res, reject: rej } = queue.shift();

        task()
          .then(res)
          .catch(rej)
          .finally(() => {
            activeCount--;
            runNext();
          });
      };

      if (activeCount < n) {
        runNext();
      }
    });
  };
}

module.exports = pLimit;
