function debounce(fn, wait, options = {}) {
  let { leading = false, trailing = true } = options;
  let timeoutId = null;
  let lastResult;
  let isTimerReset = false;
  let context;
  let args;

  const invoke = () => {
    lastResult = fn.apply(context, args);
  };

  const debounced = function(...args) {
    context = this;
    args = args;

    if (!timeoutId) {
      if (leading) {
        invoke();
      }
      isTimerReset = false;
      timeoutId = setTimeout(() => {
        if (trailing && (!leading || isTimerReset)) {
          invoke();
        }
        timeoutId = null;
        isTimerReset = false;
      }, wait);
    } else {
      clearTimeout(timeoutId);
      isTimerReset = true;
      timeoutId = setTimeout(() => {
        if (trailing && (!leading || isTimerReset)) {
          invoke();
        }
        timeoutId = null;
        isTimerReset = false;
      }, wait);
    }

    return lastResult;
  };

  debounced.cancel = () => {
    clearTimeout(timeoutId);
    timeoutId = null;
    isTimerReset = false;
  };

  debounced.flush = () => {
    if (timeoutId) {
      if (trailing && (!leading || isTimerReset)) {
        invoke();
      }
      clearTimeout(timeoutId);
      timeoutId = null;
      isTimerReset = false;
    }
    return lastResult;
  };

  return debounced;
}

module.exports = debounce;
