const jsonPointer = {
  get(doc, pointer) {
    if (pointer === "") return doc;
    if (!pointer.startsWith("/")) {
      throw new Error("Invalid pointer: must start with /");
    }

    const tokens = pointer.slice(1).split("/");
    let current = doc;

    for (const token of tokens) {
      if (current === null || current === undefined) return undefined;

      const decodedToken = token.replace(/~[01]/g, (m) => (m === "~1" ? "/" : "~"));

      if (/^\d+$/.test(decodedToken)) {
        current = current[decodedToken];
      } else if (decodedToken === "-") {
        return undefined;
      } else {
        current = current[decodedToken];
      }
    }

    return current;
  },

  set(doc, pointer, value) {
    if (pointer === "") return doc;
    if (!pointer.startsWith("/")) {
      throw new Error("Invalid pointer: must start with /");
    }

    const tokens = pointer.slice(1).split("/");
    let current = doc;

    for (let i = 0; i < tokens.length; i++) {
      const token = tokens[i];
      const isLast = i === tokens.length - 1;
      const decodedToken = token.replace(/~[01]/g, (m) => (m === "~1" ? "/" : "~"));

      if (isLast) {
        if (decodedToken === "-") {
          if (!Array.isArray(current)) {
            current[decodedToken] = [];
          }
          current[decodedToken].push(value);
        } else {
          current[decodedToken] = value;
        }
        break;
      }

      const isNumeric = /^\d+$/.test(decodedToken);
      const isDash = decodedToken === "-";

      if (isNumeric || isDash) {
        if (!Array.isArray(current)) {
          if (!(decodedToken in current)) {
            current[decodedToken] = [];
          }
        }
        current = current[decodedToken];
      } else {
        if (typeof current !== "object" || current === null) {
          current = {};
          // Note: This part handles the "creates missing intermediate objects" 
          // by ensuring we have an object to set the next property on.
          // However, if the current value was a primitive, we overwrite it 
          // to satisfy the "creates missing intermediate" requirement.
          // To strictly follow "creates missing", we only set if it's missing.
          // But since we need to traverse, if it's a primitive, we must 
          // treat it as missing/invalid for the path.
        }
        current = current[decodedToken];
      }
    }

    return doc;
  },
};

module.exports = jsonPointer;
