function singleFlight(loader) {
  const cache = new Map();
  let inflightCount = 0;

  const load = async (key) => {
    if (cache.has(key)) {
      return cache.get(key);
    }

    inflightCount++;
    const promise = loader(key).finally(() => {
      cache.delete(key);
      inflightCount--;
    });

    cache.set(key, promise);
    return promise;
  };

  Object.defineProperty(load, 'inflight', {
    get: () => inflightCount,
    configurable: true
  });

  return load;
}

module.exports = singleFlight;
