class Emitter {
  constructor() {
    this._events = new Map();
  }

  on(event, fn) {
    if (!this._events.has(event)) {
      this._events.set(event, []);
    }
    const listener = { fn, once: false };
    this._events.get(event).push(listener);
    return () => this.off(event, fn);
  }

  once(event, fn) {
    if (!this._events.has(event)) {
      this._events.set(event, []);
    }
    const listener = { fn, once: true };
    this._events.get(event).push(listener);
    return () => this.off(event, fn);
  }

  off(event, fn) {
    const listeners = this._events.get(event);
    if (!listeners) return;
    const index = listeners.findIndex((l) => l.fn === fn);
    if (index !== -1) {
      listeners.splice(index, 1);
    }
  }

  emit(event, ...args) {
    const listeners = this._events.get(event);
    if (!listeners) return 0;

    const snapshot = [...listeners];
    let count = 0;
    let firstError = null;

    for (const listener of snapshot) {
      // If a listener was removed by a previous one during this emit, skip it.
      if (!listeners.includes(listener)) {
        continue;
      }

      // If it's a 'once' listener, remove it before running.
      if (listener.once) {
        const idx = listeners.indexOf(listener);
        if (idx !== -1) {
          listeners.splice(idx, 1);
        }
      }

      try {
        listener.fn(...args);
        count++;
      } catch (e) {
        if (!firstError) {
          firstError = e;
        }
      }
    }

    if (firstError) {
      throw firstError;
    }

    return count;
  }
}

module.exports = Emitter;
