    resultText += strings[i];
    if (i < values.length) {
      const val = values[i];

      if (val && typeof val === 'object' && 'text' in val && 'values' in val) {
        // Nested sqlTag result: inline its text and merge its values
        let count = 0;
        const inlinedText = val.text.replace(/\$\d+/g, () => {
          count++;
          return `$${placeholderIndex + count - 1}`;
        });
        resultText += inlinedText;
        resultValues.push(...val.values);
        placeholderIndex += val.values.length;
      } else if (Array.isArray(val)) {
        // Array: parenthesised comma-separated list of placeholders
        const placeholders = val.map((_, idx) => `$${placeholderIndex + idx}`).join(', ');
        resultText += `(${placeholders})`;
        resultValues.push(...val);
        placeholderIndex += val.length;
      } else {
        // Primitive value
        resultText += `$${placeholderIndex}`;
        resultValues.push(val);
        placeholderIndex++;
      }
    }
  }

  return { text: resultText, values: resultValues };
}

module.exports = sqlTag;
