function* zipLongest(fill, ...iterables) {
  if (iterables.length === 0) return;

  const iterators = iterables.map(it => Symbol.iterator.call(it));
  const finished = new Array(iterators.length).fill(false);

  while (true) {
    const row = [];
    let allFinished = true;

    for (let i = 0; i < iterators.length; i++) {
      if (finished[i]) {
        row.push(fill);
      } else {
        const { value, done } = iterators[i].next();
        if (done) {
          finished[i] = true;
          row.push(fill);
        } else {
          row.push(value);
          allFinished = false;
        }
      }
    }

    if (allFinished) break;

    yield row;
  }
}

module.exports = zipLongest;
