module.exports = async function toposortTasks(tasks) {
  const taskNames = Object.keys(tasks);
  const inDegree = {};
  const dependents = {};

  // Initialize structures
  for (const name of taskNames) {
    inDegree[name] = 0;
    dependents[name] = [];
  }

  // Build graph and validate dependencies
  for (const name of taskNames) {
    for (const dep of tasks[name].deps) {
      if (!(dep in tasks)) {
        throw new Error(`Missing dependency: ${dep}`);
      }
      dependents[dep].push(name);
      inDegree[name]++;
    }
  }

  // Cycle detection using DFS
  const visited = new Set();
  const stack = new Set();
  function hasCycle(name) {
    visited.add(name);
    stack.add(name);
    for (const dep of tasks[name].deps) {
      if (stack.has(dep)) return true;
      if (!visited.has(dep) && hasCycle(dep)) return true;
    }
    stack.delete(name);
    return false;
  }

  for (const name of taskNames) {
    if (!visited.has(name) && hasCycle(name)) {
      throw new Error("Dependency cycle detected");
    }
  }

  let firstError = null;
  const results = {};
  let completedCount = 0;
  const blocked = new Set();

  return new Promise((resolve, reject) => {
    const checkDone = () => {
      if (completedCount === taskNames.length) {
        if (firstError) reject(firstError);
        else resolve(results);
      }
    };

    const runTask = async (name) => {
      // If already blocked by a failed dependency, do nothing
      if (blocked.has(name)) return;

      try {
        const args = {};
        for (const dep of tasks[name].deps) {
          args[dep] = results[dep];
        }
        results[name] = await tasks[name].run(args);

        for (const dep of dependents[name]) {
          inDegree[dep]--;
          if (inDegree[dep] === 0) {
            runTask(dep);
          }
        }
      } catch (e) {
        if (!firstError) firstError = e;

        const markBlocked = (n) => {
          if (!blocked.has(n)) {
            blocked.add(n);
            completedCount++;
            checkDone();
            for (const d of dependents[n]) {
              markBlocked(d);
            }
          }
        };

        for (const dep of dependents[name]) {
          markBlocked(dep);
        }
      } finally {
        completedCount++;
        checkDone();
      }
    };

    // Start all tasks with no dependencies
    taskNames.forEach((name) => {
      if (inDegree[name] === 0) {
        runTask(name);
      }
    });
  });
};
