export class Bus<E extends Record<string, unknown>> {
  private handlers = new Map<string, Set<(payload: unknown) => void>>();

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    let set = this.handlers.get(k);
    if (!set) {
      set = new Set();
      this.handlers.set(k, set);
    }

    const wrapper = (payload: unknown) => fn(payload as E[K]);
    set.add(wrapper);

    return () => {
      const set_ = this.handlers.get(k);
      set_?.delete(wrapper);
    };
  }

  emit<K extends keyof E>(k: K, ...args: E[K] extends void ? [] : [E[K]]) {
    const set = this.handlers.get(k);
    if (set) {
      const payload = args[0];
      set.forEach((handler) => handler(payload));
    }
  }
}
