export async function deepAwait<T>(input: T): Promise<DeepAwaited<T>> {
  if (input instanceof Promise) {
    const resolved = await input;
    return deepAwait(resolved) as any;
  }

  if (Array.isArray(input)) {
    return Promise.all(input.map((item) => deepAwait(item))) as any;
  }

  if (input !== null && typeof input === 'object' && typeof input !== 'function') {
    if (input instanceof Date || input instanceof RegExp) {
      return input as any;
    }

    const result: any = {};
    const keys = Object.keys(input);
    for (const key of keys) {
      result[key] = await deepAwait(input[key]);
    }
    return result;
  }

  return input as any;
}
