export type DeepPartial<T> = T extends Function
  ? T
  : T extends Array<any>
  ? T
  : T extends object
  ? { [K in keyof T]?: DeepPartial<T[K]> }
  : T | undefined;

export function applyPatch<T extends object>(base: T, patch: DeepPartial<T>): T {
  if (patch === undefined) {
    return base;
  }

  if (patch === null || typeof patch !== 'object' || Array.isArray(patch)) {
    return patch as unknown as T;
  }

  const result = { ...base } as any;

  for (const key in patch) {
    const patchValue = (patch as any)[key];

    if (patchValue !== undefined) {
      const baseValue = (base as any)[key];

      if (Array.isArray(patchValue)) {
        result[key] = patchValue;
      } else if (
        patchValue !== null &&
        typeof patchValue === 'object' &&
        !Array.isArray(patchValue) &&
        typeof patchValue !== 'function'
      ) {
        const nextBase = (baseValue !== null && typeof baseValue === 'object') ? baseValue : {};
        result[key] = applyPatch(nextBase as any, patchValue);
      } else {
        result[key] = patchValue;
      }
    }
  }

  return result as T;
}
